import { Group, Mesh, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  texture,
  color,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();
  group.name = 'home-headline';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkColor = color(colors.ink);
  const surfaceColor = color(colors.surface);
  const paperColor = color(colors.paper);

  // ---- Backdrop plane: engineered gradient + subtle grain ----
  const width = 5.6;
  const height = 1.3;
  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshBasicNodeMaterial({ side: DoubleSide });

  const uvNode = uv();

  // Vertical engineered gradient: surface (bottom) -> ink (top)
  const gradientFactor = smoothstep(float(0.0), float(1.0), uvNode.y);
  const baseGradient = mix(surfaceColor, inkColor, gradientFactor);

  // Subtle grain using a pseudo-random hash, low amplitude, static (no time dependence)
  const grainSeed = dot(uvNode.mul(vec2(12.9898, 78.233)), vec2(1.0, 1.0));
  const grain = fract(sin(grainSeed).mul(43758.5453)).sub(0.5).mul(0.035);

  const grainedGradient = baseGradient.add(vec3(grain, grain, grain));

  // Fold in the source texture as a faint engineered surface layer
  let colorNode = grainedGradient;
  const opacityUniform = uniform(0.0);
  material.opacityNode = opacityUniform;
  material.transparent = true;

  if (config.imageUrl) {
    const texUniformHolder = { tex: null };
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texUniformHolder.tex = tex;
      const texNode = texture(tex, uvNode);
      // Blend the mock texture subtly beneath the gradient/grain so the
      // gradient + grain remain the dominant engineered surface.
      material.colorNode = mix(grainedGradient, texNode, float(0.18));
      material.needsUpdate = true;
    });
  }

  material.colorNode = colorNode;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // ---- Text content ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.02);
  group.add(textGroup);

  let yCursor = 0.0;
  for (const item of items) {
    const role = item.role ?? 'body';
    const rawSize = item.typography?.fontSize ?? 31;
    // convert px hint roughly into a legible atlas font size
    const fontSize = Math.max(28, Math.min(48, rawSize));
    const textColor = colors.paper;

    const textObj = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: textColor,
      align: 'left',
      maxWidthPx: 900,
    });
    textObj.position.set(-width / 2 + 0.4, yCursor, 0);
    textGroup.add(textObj);
    yCursor -= 0.4;
  }

  // ---- Cinematic primitives (none specified for this node) ----
  const primitiveHandles = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveConfigs) {
    const applyPrimitive = ctx.primitives[prim.name];
    if (applyPrimitive) {
      const handle = applyPrimitive(group, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // ---- Weighted entrance motion (fade-up, power-out, no linear easing) ----
  textGroup.position.y -= 0.2;
  const timeline = gsap.timeline();
  timeline.to(opacityUniform, {
    value: 1.0,
    duration: 0.7,
    ease: 'power2.out',
  });
  timeline.to(
    textGroup.position,
    {
      y: textGroup.position.y + 0.2,
      duration: 0.8,
      ease: 'power3.out',
    },
    0
  );

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timeline.kill();
    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }
    geometry.dispose();
    material.dispose();
    for (const child of textGroup.children) {
      child.geometry?.dispose?.();
      child.material?.dispose?.();
    }
  };

  return group;
}
